recipes.code:
{
  "inputs": [
    {
      "id": "soapnoteapi-key",
      "type": "promptString",
      "description": "SOAPNoteAPI Bearer key (snapi_sk_...). Get one at https://app.soapnoteapi.com",
      "password": true
    }
  ],
  "servers": {
    "soapnoteapi": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "soapnoteapi-mcp@0.1.1"
      ],
      "env": {
        "SOAPNOTEAPI_KEY": "${input:soapnoteapi-key}"
      }
    }
  }
}
